 * A hand-rolled scanner for the toy language described in the task. `scan`
 * turns UTF-8 source text into a flat array of tokens, or throws a
 * `LexError` at the first offending position.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

export class LexError extends Error {
  constructor(reason, pos) {
    super(reason)
    this.pos = pos
  }
}

function isIdentStart(c) {
  return c === '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

function isIdentPart(c) {
  return isIdentStart(c) || (c >= '0' && c <= '9')
}

function isDecDigit(c) {
  return c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return isDecDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isOctDigit(c) {
  return c >= '0' && c <= '7'
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

// Word characters are the ones that would extend an identifier; a number
// immediately followed by one of these (that the number grammar itself did
// not consume) is an error.
function isWordChar(c) {
  return isIdentPart(c)
}

// A tab moves the column to the next multiple of 4, plus 1.
function stepPos(line, col, ch) {
  if (ch === '\n') return { line: line + 1, col: 1 }
  if (ch === '\t') return { line, col: Math.floor((col - 1) / 4) * 4 + 5 }
  return { line, col: col + 1 }
}

function makeState(input) {
  return { cps: Array.from(input), i: 0, line: 1, col: 1 }
}

function here(st) {
  return { line: st.line, col: st.col }
}

function advance(st) {
  const ch = st.cps[st.i]
  const next = stepPos(st.line, st.col, ch)
  st.line = next.line
  st.col = next.col
  st.i++
  return ch
}

function atEnd(st) {
  return st.i >= st.cps.length
}

function peek(st, offset = 0) {
  return st.cps[st.i + offset]
}

// Consumes a run of digits matching `testFn`, allowing a single `_` between
// two digits of the run. Returns the number of digits consumed.
function consumeDigitRun(st, testFn) {
  let count = 0
  while (!atEnd(st)) {
    const c = peek(st)
    if (testFn(c)) {
      advance(st)
      count++
    } else if (c === '_' && count > 0 && testFn(peek(st, 1))) {
      advance(st)
    } else {
      break
    }
  }
  return count
}

function skipLineComment(st) {
  advance(st)
  advance(st)
  while (!atEnd(st) && peek(st) !== '\n') advance(st)
}

function skipBlockComment(st) {
  const startPos = here(st)
  advance(st)
  advance(st)
  let depth = 1
  while (depth > 0) {
    if (atEnd(st)) throw new LexError('unterminated block comment', startPos)
    if (peek(st) === '/' && peek(st, 1) === '*') {
      advance(st)
      advance(st)
      depth++
    } else if (peek(st) === '*' && peek(st, 1) === '/') {
      advance(st)
      advance(st)
      depth--
    } else {
      advance(st)
    }
  }
}

function scanIdent(st) {
  const startPos = here(st)
  const startIdx = st.i
  advance(st)
  while (!atEnd(st) && isIdentPart(peek(st))) advance(st)
  const text = st.cps.slice(startIdx, st.i).join('')
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, text, pos: startPos }
}

function scanNumber(st) {
  const startPos = here(st)
  const startIdx = st.i
  let prefixNoDigit = false

  const c0 = peek(st)
  if (c0 === '0' && /[xXbBoO]/.test(peek(st, 1) ?? '')) {
    const prefix = peek(st, 1).toLowerCase()
    advance(st)
    advance(st)
    const testFn = prefix === 'x' ? isHexDigit : prefix === 'b' ? isBinDigit : isOctDigit
    const count = consumeDigitRun(st, testFn)
    if (count === 0) prefixNoDigit = true
  } else {
    consumeDigitRun(st, isDecDigit)
    if (peek(st) === '.' && isDecDigit(peek(st, 1) ?? '')) {
      advance(st)
      consumeDigitRun(st, isDecDigit)
    }
    if (/[eE]/.test(peek(st) ?? '')) {
      const afterE = peek(st, 1)
      if (isDecDigit(afterE ?? '')) {
        advance(st)
        consumeDigitRun(st, isDecDigit)
      } else if (/[+-]/.test(afterE ?? '') && isDecDigit(peek(st, 2) ?? '')) {
        advance(st)
        advance(st)
        consumeDigitRun(st, isDecDigit)
      }
    }
  }

  const trailing = !atEnd(st) && isWordChar(peek(st))
  if (prefixNoDigit || trailing) {
    while (!atEnd(st) && isWordChar(peek(st))) advance(st)
    const text = st.cps.slice(startIdx, st.i).join('')
    throw new LexError(`invalid number ${text}`, startPos)
  }

  const text = st.cps.slice(startIdx, st.i).join('')
  return { kind: 'number', text, pos: startPos }
}

