      if (ec === 'n') {
        decoded += '\n'
        advance(st)
      } else if (ec === 't') {
        decoded += '\t'
        advance(st)
      } else if (ec === 'r') {
        decoded += '\r'
        advance(st)
      } else if (ec === '\\') {
        decoded += '\\'
        advance(st)
      } else if (ec === '"') {
        decoded += '"'
        advance(st)
      } else if (ec === '0') {
        decoded += '\0'
        advance(st)
      } else if (ec === 'x') {
        advance(st)
        let hex = ''
        for (let k = 0; k < 2; k++) {
          if (atEnd(st)) throw new LexError('unterminated string', startPos)
          const hc = peek(st)
          if (!isHexDigit(hc)) throw new LexError('invalid escape \\x', bsPos)
          hex += hc
          advance(st)
        }
        decoded += String.fromCharCode(parseInt(hex, 16))
      } else if (ec === 'u') {
        advance(st)
        if (atEnd(st)) throw new LexError('unterminated string', startPos)
        if (peek(st) !== '{') throw new LexError('invalid escape \\u', bsPos)
        advance(st)
        let hex = ''
        for (;;) {
          if (atEnd(st)) throw new LexError('unterminated string', startPos)
          const hc = peek(st)
          if (hc === '}') break
          if (!isHexDigit(hc)) throw new LexError('invalid escape \\u', bsPos)
          hex += hc
          advance(st)
        }
        if (hex.length === 0) throw new LexError('invalid escape \\u', bsPos)
        advance(st)
        const cp = parseInt(hex, 16)
        if (cp > 0x10ffff) throw new LexError('invalid escape \\u', bsPos)
        decoded += String.fromCodePoint(cp)
      } else {
        throw new LexError(`invalid escape \\${ec}`, bsPos)
      }
    } else {
      decoded += ch
      advance(st)
    }
  }
  return { kind: 'string', text: JSON.stringify(decoded), pos: startPos }
}

function scanRawString(st) {
  const startPos = here(st)
  advance(st)
  advance(st)
  let decoded = ''
  for (;;) {
    if (atEnd(st)) throw new LexError('unterminated string', startPos)
    const ch = peek(st)
    if (ch === '"') {
      advance(st)
      break
    }
    decoded += ch
    advance(st)
  }
  return { kind: 'rawstring', text: JSON.stringify(decoded), pos: startPos }
}

function scanPunct(st) {
  const startPos = here(st)
  const c0 = peek(st)
  const c1 = peek(st, 1)
  if (c1 !== undefined && TWO_CHAR_PUNCT.has(c0 + c1)) {
    advance(st)
    advance(st)
    return { kind: 'punct', text: c0 + c1, pos: startPos }
  }
  if (ONE_CHAR_PUNCT.has(c0)) {
    advance(st)
    return { kind: 'punct', text: c0, pos: startPos }
  }
  return null
}

/**
 * Scans `input` into a flat array of `{ kind, text, pos }` tokens, or throws
 * a `LexError` at the first offending position.
 */
export function scan(input) {
  const st = makeState(input)
  const tokens = []
  while (!atEnd(st)) {
    const ch = peek(st)
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      advance(st)
      continue
    }
    if (ch === '/' && peek(st, 1) === '/') {
      skipLineComment(st)
      continue
    }
    if (ch === '/' && peek(st, 1) === '*') {
      skipBlockComment(st)
      continue
    }
    if (ch === '"') {
      tokens.push(scanString(st))
      continue
    }
    if (ch === 'r' && peek(st, 1) === '"') {
      tokens.push(scanRawString(st))
      continue
    }
    if (isIdentStart(ch)) {
      tokens.push(scanIdent(st))
      continue
    }
    if (isDecDigit(ch)) {
      tokens.push(scanNumber(st))
      continue
    }
    const punct = scanPunct(st)
    if (punct) {
      tokens.push(punct)
      continue
    }
    throw new LexError(`unexpected character ${ch}`, here(st))
  }
  return tokens
}
