  let out = ''
  for (const token of tokens) {
    out += `${token.pos.line}:${token.pos.col} ${token.kind} ${token.text}\n`
  }
  process.stdout.write(out)
} else {
  const counts = Object.fromEntries(STAT_KINDS.map((kind) => [kind, 0]))
  for (const token of tokens) counts[token.kind]++
  let out = ''
  for (const kind of STAT_KINDS) out += `${kind} ${counts[kind]}\n`
  out += `total ${tokens.length}\n`
  process.stdout.write(out)
}
